"use strict";

let canvas = document.getElementById("canvas");
let ctx = canvas.getContext("2d");

let gravity = 0.0981; // m/s^2
let initialAngle = 0;
let angle = 0;
let velocity = 0;
let swingAngle = 0;
let maxWidth = canvas.width;

let isRunning = false;

document.getElementById("start-button").addEventListener("click", () => {
    isRunning = true;
    initialAngle = parseFloat(document.getElementById("initial-angle").value);
    angle = initialAngle;
    velocity = 0;
    swingAngle = 0;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.beginPath();
    ctx.arc(canvas.width / 2, canvas.height / 2, 100, 0, 2 * Math.PI);
    ctx.stroke();

    draw();
});

function draw() {
    if (isRunning) {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        ctx.beginPath();
        let radius = 100;
        let x = Math.cos(Math.PI / 180 * angle) * radius;
        let y = Math.sin(Math.PI / 180 * angle) * radius;
        ctx.moveTo(canvas.width / 2, canvas.height / 2);
        ctx.lineTo(canvas.width / 2 + x, canvas.height / 2 - y);
        ctx.stroke();

        // Update pendulum movement
        velocity += gravity * Math.sin(Math.PI / 180 * angle);
        angle += velocity;
        swingAngle += velocity;

        // Update position
        if (swingAngle > maxWidth) {
            swingAngle = 2 * Math.PI - swingAngle;
            velocity = -velocity;
        }

        if (swingAngle < -maxWidth) {
            swingAngle = -2 * Math.PI + swingAngle;
            velocity = -velocity;
        }

        requestAnimationFrame(draw);
    }
}
```

